void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void write(const std::filesystem::path& path,const std::string& text){std::ofstream file(path,std::ios::binary);file.write(text.data(),text.size());if(!file)throw std::runtime_error("fixture write");}
template<class F>void reject(F action,const char* message){bool rejected=false;try{action();}catch(...){rejected=true;}check(rejected,message);}
